"use client";

import { useActionState, useEffect, useState } from "react";
import { topUp } from "@/lib/actions";
import { Badge } from "@/components/ui/primitives";
import { AddFundsPaymentModal } from "@/components/customer/AddFundsPaymentModal";

const PRESETS = [10, 25, 50, 100];

function DemoTopUp() {
  const [state, action, pending] = useActionState(topUp, {});
  // CONTROLLED, deliberately. React 19 resets uncontrolled fields on every
  // `<form action={fn}>` submit — including a REJECTED one. `topUp` returns
  // `{error}`, so an uncontrolled amount snapped back to the default while the
  // error pointed at a figure no longer on screen. Same reset class as
  // AutoRecharge.tsx.
  const [amount, setAmount] = useState("25");
  return (
    <div>
      <div className="mb-3 flex items-center gap-2">
        <Badge tone="amber">demo gateway</Badge>
        <span className="text-xs text-slate-500">
          Card payments are not configured — funds are credited instantly for testing.
        </span>
      </div>
      <form action={action} className="flex items-end gap-3">
        <div>
          <label className="label">Amount (USD)</label>
          <input
            className="input w-36"
            name="amount"
            type="number"
            min={1}
            max={1000}
            step="0.01"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
          />
        </div>
        <button className="btn-primary" disabled={pending}>
          {pending ? "Adding…" : "Add funds"}
        </button>
        {state?.error && <span className="text-sm text-red-400">{state.error}</span>}
      </form>
    </div>
  );
}

export function AddFunds() {
  const [amount, setAmount] = useState<string>("25");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [demoMode, setDemoMode] = useState(false);
  const [session, setSession] = useState<{
    clientSecret: string; publishableKey: string;
    local?: { label: string; currency: string; chargeCents: number | null };
  } | null>(null);
  // Local payment methods switched on for this account (default: none, so the
  // picker below never renders). Wallet top-up only — see lib/local-payment-methods.ts.
  const [localMethods, setLocalMethods] = useState<{ id: string; label: string; note: string; currency: string }[]>([]);
  const [method, setMethod] = useState<string>("card");
  useEffect(() => {
    let live = true;
    fetch("/api/stripe/local-methods")
      .then((r) => (r.ok ? r.json() : { methods: [] }))
      .then((j: { methods?: { id: string; label: string; note: string; currency: string }[] }) => {
        if (live && Array.isArray(j.methods)) setLocalMethods(j.methods);
      })
      .catch(() => { /* picker simply stays hidden */ });
    return () => { live = false; };
  }, []);

  if (demoMode) return <DemoTopUp />;

  const checkout = async () => {
    setBusy(true);
    setError(null);
    try {
      const res = await fetch("/api/stripe/checkout", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ amount: Number(amount), method }),
      });
      const json: { clientSecret?: string; publishableKey?: string; error?: string; charge?: { currency: string; cents: number | null } } = await res
        .json()
        .catch(() => ({}));
      if (json.clientSecret && json.publishableKey) {
        // Pay in the embedded modal on THIS page — no redirect to Stripe.
        const lm = method === "card" ? undefined : localMethods.find((m) => m.id === method);
        setSession({
          clientSecret: json.clientSecret, publishableKey: json.publishableKey,
          local: lm ? { label: lm.label, currency: json.charge?.currency ?? lm.currency, chargeCents: json.charge?.cents ?? null } : undefined,
        });
        setBusy(false);
        return;
      }
      const msg = json.error ?? "Checkout failed — try again.";
      if (msg.toLowerCase().includes("not configured")) {
        setDemoMode(true);
      } else {
        setError(msg);
      }
    } catch {
      setError("Network error — try again.");
    }
    setBusy(false);
  };

  const n = Number(amount);
  const valid = Number.isFinite(n) && n >= 5 && n <= 5000;

  return (
    <div>
      <div className="flex flex-wrap items-end gap-3">
        <div>
          <label className="label">Amount (USD)</label>
          <div className="flex items-center gap-2">
            {PRESETS.map((p) => (
              <button
                key={p}
                type="button"
                onClick={() => setAmount(String(p))}
                className={`chip h-[30px] px-3 text-[12px] ${amount === String(p) ? "chip-on" : ""}`}
              >
                ${p}
              </button>
            ))}
            <input
              className="input w-28"
              type="number"
              min={5}
              max={5000}
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
            />
          </div>
        </div>
        <button className="btn-primary" onClick={() => void checkout()} disabled={busy || !valid}>
          {busy ? "Loading…" : "Add funds"}
        </button>
      </div>
      {localMethods.length > 0 && (
        <div className="mt-3">
          <label className="label">Pay with</label>
          <div className="flex flex-wrap items-center gap-2">
            {[{ id: "card", label: "Card", note: "" }, ...localMethods].map((m) => (
              <button
                key={m.id}
                type="button"
                onClick={() => setMethod(m.id)}

                onClick={() => setMethod(m.id)}
                className={`chip h-[30px] px-3 text-[12px] ${method === m.id ? "chip-on" : ""}`}
              >
                {m.label}
              </button>
            ))}
          </div>
          {method !== "card" && (
            <p className="mt-2 text-xs text-slate-500">
              {localMethods.find((m) => m.id === method)?.note} This adds funds to your wallet as a one-time payment. It
              is not saved for renewals, so renewals keep drawing on your wallet balance or a saved card.
            </p>
          )}
        </div>
      )}
      {!valid && amount !== "" && (
        <p className="mt-2 text-xs text-amber-300">Amount must be between $5 and $5000.</p>
      )}
      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
      <p className="mt-2 text-xs text-slate-500">Secure card checkout powered by Stripe.</p>
      {session && (
        <AddFundsPaymentModal
          clientSecret={session.clientSecret}
          publishableKey={session.publishableKey}
          amountCents={Math.round(n * 100)}
          local={session.local}
          onClose={() => setSession(null)}
        />
      )}
    </div>
  );
}
