/**
 * In-place wallet top-up completion (the portal sidebar's "Add funds" popup,
 * components/nx/AddFundsDialog.tsx).
 *
 * The Billing page's top-up confirms with Stripe's default `redirect: "always"`:
 * Stripe navigates the browser to `/api/stripe/confirm`, which fulfils and
 * bounces to `/dashboard/billing?paid=1`. The popup instead confirms with
 * `redirect: "if_required"` so a card payment (including 3-D Secure, which
 * Stripe runs in its own overlay) resolves IN the page, then POSTs the session
 * id to `/api/stripe/topup-complete`, which runs the exact same idempotent
 * `fulfilCheckoutSession` the confirm route and the webhook run — whichever of
 * the three arrives first credits the wallet, the others are no-ops (UNIQUE
 * stripeSessionId on the WalletTransaction). Methods that genuinely need a
 * redirect (some local methods) still redirect and land on Billing as before.
 *
 * This module holds the one decision that endpoint makes before it reports a
 * balance back to the browser, kept pure so it is unit-tested without Stripe.
 */

export type TopUpSessionLike = {
  /** `nxeonUserId` is what `creditCheckoutSession` credits (lib/stripe.ts). */
  metadata?: Record<string, string> | null;
  payment_status?: string | null;
  status?: string | null;
};

export type TopUpCompletion =
  /** Paid and owned by the caller: fulfil, then report the fresh balance. */
  | { kind: "ok" }
  /** Session belongs to another account: never fulfil-and-report for it. */
  | { kind: "forbidden" }
  /** Not paid (yet): a delayed local method, or an abandoned/replayed id. */
  | { kind: "pending" };

export function decideTopUpCompletion(session: TopUpSessionLike, userId: string): TopUpCompletion {
  const owner = session.metadata?.nxeonUserId;
  if (!owner || owner !== userId) return { kind: "forbidden" };
  if (session.payment_status !== "paid") return { kind: "pending" };
  return { kind: "ok" };
}

/** Stripe Checkout Session ids are `cs_test_…` / `cs_live_…`. Reject anything else before a network call. */
export function looksLikeCheckoutSessionId(id: unknown): id is string {
  return typeof id === "string" && /^cs_(test|live)_[A-Za-z0-9]{10,200}$/.test(id);
}

/** Wallet top-up presets shown in the popup (USD). Same set the Billing page offers. */
export const TOPUP_PRESETS = [10, 25, 50, 100] as const;

/**
 * Client-side amount check mirroring /api/stripe/checkout ($5..$5000 and the
 * admin minimum, which the server enforces again — this only stops an obviously
 * bad request and words the reason).
 */
