import { NextRequest, NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { stripeConfigured, retrieveCheckoutSession } from "@/lib/stripe";
import { fulfilRetrievedCheckoutSession } from "@/lib/fulfil-checkout";
import { decideTopUpCompletion, looksLikeCheckoutSessionId } from "@/lib/topup-inplace";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

export const dynamic = "force-dynamic";

/**
 * Completes a wallet top-up paid IN PLACE from the portal's "Add funds" popup
 * (components/nx/AddFundsDialog.tsx -> AddFundsPaymentModal's `onPaid` path,
 * which confirms with `redirect: "if_required"`). See lib/topup-inplace.ts.
 *
 * It does not own fulfilment: it calls the same idempotent fulfilment the
 * /api/stripe/confirm redirect and the Stripe webhook call, against a session
 * re-read from Stripe (never trusting the browser's word that it was paid),
 * and only for a session whose `nxeonUserId` is the signed-in account. Then it
 * returns the account's fresh balance so the popup can show it.
 */
export async function POST(req: NextRequest) {
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "Please sign in again." }, { status: 401, headers: NO_STORE_HEADERS });
  if (!stripeConfigured()) return NextResponse.json({ error: "Card payments aren't available right now." }, { status: 400, headers: NO_STORE_HEADERS });

  const body = (await req.json().catch(() => ({}))) as { sessionId?: unknown };
  if (!looksLikeCheckoutSessionId(body.sessionId)) {
    return NextResponse.json({ error: "That payment reference isn't valid." }, { status: 400, headers: NO_STORE_HEADERS });
  }

  let session;
  try {
    session = await retrieveCheckoutSession(body.sessionId);
  } catch {
    // The webhook is the independent backstop; the money is not lost.
    return NextResponse.json({ status: "pending" }, { headers: NO_STORE_HEADERS });
  }

  const decision = decideTopUpCompletion(session as { metadata?: Record<string, string> | null; payment_status?: string | null }, user.id);
  if (decision.kind === "forbidden") {
    return NextResponse.json({ error: "That payment belongs to a different account." }, { status: 403, headers: NO_STORE_HEADERS });
  }
  if (decision.kind === "pending") {
    return NextResponse.json({ status: "pending" }, { headers: NO_STORE_HEADERS });
  }

  try {
    await fulfilRetrievedCheckoutSession(session);
  } catch (e) {
    console.error("[topup-complete] fulfilment threw; webhook will retry", body.sessionId, e instanceof Error ? e.message : e);
    return NextResponse.json({ status: "pending" }, { headers: NO_STORE_HEADERS });
  }
  const fresh = await db.user.findUnique({ where: { id: user.id }, select: { balanceCents: true } });
  return NextResponse.json(
    { status: "paid", balanceCents: fresh?.balanceCents ?? null, creditedCents: session.amount_total ?? null },
    { headers: NO_STORE_HEADERS },
  );
}
EOF

