"use client";

/**
 * The portal sidebar's "Add funds" popup: tops the wallet up WITHOUT leaving
 * the page the customer is on.
 *
 * It is the Billing page's top-up, not a second payment path:
 *  - the amount goes to the same `/api/stripe/checkout` (same min/max, same
 *    stale-coupon refusal, same local-method gating via /api/stripe/local-methods),
 *  - the card step is `TopUpPayment` from AddFundsPaymentModal.tsx (same Stripe
 *    Custom Checkout elements, appearance and theme keying),
 *  - fulfilment is the same idempotent `fulfilCheckoutSession`, reached through
 *    /api/stripe/topup-complete instead of a redirect (lib/topup-inplace.ts).
 * On success it `router.refresh()`es so the sidebar balance (rendered by the
 * dashboard layout) shows the new figure, and says so in the dialog.
 *
 * Without Stripe (local dev / sandbox with no keys) it uses the same demo
 * `topUp` server action the Billing page's DemoTopUp uses, which refuses in
 * production on its own.
 */

import { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { Icon } from "./Icon";
import { TopUpPayment, type LocalPay } from "@/components/customer/AddFundsPaymentModal";
import { topUp } from "@/lib/actions";
import { TOPUP_PRESETS, validateTopUpAmount } from "@/lib/topup-inplace";

type LocalMethod = { id: string; label: string; note: string; currency: string };
type Step =
  | { s: "amount" }
  | { s: "pay"; clientSecret: string; publishableKey: string; cents: number; local?: LocalPay }
  | { s: "done"; cents: number; balanceCents: number | null }
  | { s: "pending"; cents: number };

const usd = (cents: number) =>
  "$" + (cents / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

export function AddFundsDialog({ balanceCents, onClose }: { balanceCents: number; onClose: () => void }) {
  const router = useRouter();
  const [step, setStep] = useState<Step>({ s: "amount" });
  const [amount, setAmount] = useState("25");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [demo, setDemo] = useState(false);
  const [localMethods, setLocalMethods] = useState<LocalMethod[]>([]);
  const [method, setMethod] = useState("card");
  const inputRef = useRef<HTMLInputElement>(null);
  const dialogRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let live = true;
    fetch("/api/stripe/local-methods")
      .then((r) => (r.ok ? r.json() : { methods: [] }))
      .then((j: { methods?: LocalMethod[] }) => { if (live && Array.isArray(j.methods)) setLocalMethods(j.methods); })
      .catch(() => { /* the picker simply stays hidden */ });
    return () => { live = false; };
  }, []);

  // Escape closes (not mid-request), focus moves into the dialog, and the
  // page behind does not scroll while it is open.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape" && !busy) onClose(); };
    document.addEventListener("keydown", onKey);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => { document.removeEventListener("keydown", onKey); document.body.style.overflow = prev; };
  }, [onClose, busy]);
  useEffect(() => { if (step.s === "amount") inputRef.current?.focus({ preventScroll: true }); }, [step.s]);

  const check = validateTopUpAmount(amount);

  async function start() {
    if (!check.ok || busy) return;
    setBusy(true);
    setError(null);
    try {
      if (demo) {
        const fd = new FormData();
        fd.set("amount", String(check.cents / 100));
        const r = await topUp({}, fd);
        if (r?.error) { setError(r.error); return; }
        router.refresh();
        setStep({ s: "done", cents: check.cents, balanceCents: balanceCents + check.cents });
        return;
      }
      const res = await fetch("/api/stripe/checkout", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ amount: check.cents / 100, method }),
      });
      const j: { clientSecret?: string; publishableKey?: string; error?: string; charge?: { currency: string; cents: number | null } } =
        await res.json().catch(() => ({}));
      if (j.clientSecret && j.publishableKey) {
        const lm = method === "card" ? undefined : localMethods.find((m) => m.id === method);
        setStep({
          s: "pay", clientSecret: j.clientSecret, publishableKey: j.publishableKey, cents: check.cents,
          local: lm ? { label: lm.label, currency: j.charge?.currency ?? lm.currency, chargeCents: j.charge?.cents ?? null } : undefined,
        });
        return;
      }
      const msg = j.error ?? "We couldn't start the payment. Please try again.";
      if (msg.toLowerCase().includes("not configured")) {
        setDemo(true);
        setError("Card payments aren't set up on this environment. Press Add funds again to use the test top-up.");
      } else setError(msg);
    } catch {
      setError("Network error. Check your connection and try again.");
    } finally {
      setBusy(false);
    }
  }

  async function onPaid(sessionId: string, cents: number) {
    try {
      const r = await fetch("/api/stripe/topup-complete", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ sessionId }),
      });
      const j: { status?: string; balanceCents?: number | null; error?: string } = await r.json().catch(() => ({}));
      router.refresh();
      if (j.status === "paid") setStep({ s: "done", cents, balanceCents: j.balanceCents ?? null });
      else setStep({ s: "pending", cents });
    } catch {
      // Paid at Stripe but we couldn't hear back: the webhook still credits it.
      router.refresh();
      setStep({ s: "pending", cents });
    }
  }

  if (typeof document === "undefined") return null;

  const title = step.s === "done" ? "Funds added" : step.s === "pending" ? "Payment processing" : "Add funds";

  return createPortal(
    <div
      className="fixed inset-0 z-[120] flex items-end justify-center overflow-y-auto bg-black/60 p-0 backdrop-blur-sm sm:items-center sm:p-6"
      onMouseDown={(e) => { if (e.target === e.currentTarget && !busy) onClose(); }}
    >
      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="nx-addfunds-title"
        data-testid="add-funds-dialog"
        className="nx-addfunds relative w-full max-w-[460px] rounded-t-[20px] border border-rim-hi bg-surface shadow-2xl sm:rounded-[18px]"
      >
        <div className="flex items-center gap-3 border-b border-rim-soft px-5 py-4">
          <span className="grid h-9 w-9 flex-none place-items-center rounded-[10px] border border-rim-hi bg-well" aria-hidden>
            <Icon name={step.s === "done" ? "checkcircle" : "card"} size={15} />
          </span>
          <span className="flex min-w-0 flex-col">
            <h2 id="nx-addfunds-title" className="truncate text-[16px] font-extrabold tracking-[-0.02em] text-white">{title}</h2>
            <p className="truncate text-[12.5px] text-tx-dim">
              Current balance <span className="num font-semibold text-tx-body">{usd(balanceCents)}</span>
            </p>
          </span>
          <button
            type="button"
            onClick={onClose}
            disabled={busy}
            aria-label="Close"
            className="ml-auto grid h-[32px] w-[32px] flex-none place-items-center rounded-[9px] text-tx-faint transition hover:bg-hover hover:text-white disabled:opacity-40"
          >
            <Icon name="xcircle" size={16} tone="inherit" />
          </button>
        </div>

        <div className="max-h-[calc(100dvh-120px)] overflow-y-auto px-5 pb-5 pt-4">
          {step.s === "amount" && (
            <form onSubmit={(e) => { e.preventDefault(); void start(); }} className="flex flex-col gap-4">
              <fieldset className="flex flex-col gap-2">
                <legend className="mb-2 text-[12px] font-bold uppercase tracking-[0.08em] text-tx-faint">Amount</legend>
                <div className="grid grid-cols-4 gap-2">
                  {TOPUP_PRESETS.map((p) => {
                    const on = amount === String(p);
                    return (
                      <button
                        key={p}
                        type="button"
                        aria-pressed={on}
                        onClick={() => { setAmount(String(p)); setError(null); }}
                        className={"nx-addfunds-preset h-[44px] rounded-[11px] border text-[15px] font-extrabold transition " +
                          (on ? "border-brand-400 bg-brand-500/15 text-white" : "border-rim-hi bg-well text-tx-body hover:border-brand-400/60 hover:text-white")}
                      >
                        ${p}
                      </button>
                    );
                  })}
                </div>
                <label htmlFor="nx-addfunds-amount" className="mt-1 text-[12.5px] font-semibold text-tx-mute">Or enter an amount (USD)</label>
                <div className="flex h-[46px] items-center gap-2 rounded-[11px] border border-rim-hi bg-well px-3 focus-within:border-brand-400">
                  <span className="text-[16px] font-bold text-tx-faint" aria-hidden>$</span>
                  <input
                    id="nx-addfunds-amount"
                    ref={inputRef}
                    inputMode="decimal"
                    autoComplete="off"
                    value={amount}
                    onChange={(e) => { setAmount(e.target.value.replace(/[^0-9.]/g, "")); setError(null); }}
                    aria-invalid={!check.ok && amount !== ""}
                    aria-describedby="nx-addfunds-hint"
                    className="num h-full min-w-0 flex-1 bg-transparent text-[18px] font-bold text-white outline-none placeholder:text-tx-faint"
                    placeholder="25.00"
                  />
                </div>
                <p id="nx-addfunds-hint" className={"text-[12px] " + (!check.ok && amount !== "" ? "text-amber" : "text-tx-faint")}>
                  {!check.ok && amount !== "" ? check.error : "Between $5 and $5,000. Your wallet pays renewals first, before any saved card."}
                </p>
              </fieldset>

              {localMethods.length > 0 && !demo && (
                <fieldset className="flex flex-col gap-2">
                  <legend className="mb-2 text-[12px] font-bold uppercase tracking-[0.08em] text-tx-faint">Pay with</legend>
                  <div className="flex flex-wrap gap-2">
                    {[{ id: "card", label: "Card", note: "", currency: "USD" }, ...localMethods].map((m) => (
                      <button
                        key={m.id}
                        type="button"
                        aria-pressed={method === m.id}
                        onClick={() => setMethod(m.id)}
                        className={"chip h-[32px] px-3 text-[12.5px] " + (method === m.id ? "chip-on" : "")}
                      >
                        {m.label}
                      </button>
                    ))}
                  </div>
                  {method !== "card" && (
                    <p className="text-[12px] leading-[1.5] text-tx-faint">
                      {localMethods.find((m) => m.id === method)?.note} A one-time payment into your wallet; it is not saved for renewals.
                    </p>
                  )}
                </fieldset>
              )}

              {error && (
                <p role="alert" className="rounded-[10px] border border-rose/35 bg-rose/10 px-3 py-2 text-[12.5px] text-rose">{error}</p>
              )}

              <button type="submit" disabled={!check.ok || busy} className="btn-primary h-[46px] w-full text-[14px]">
                {busy ? "Starting secure checkout…" : check.ok ? `Add ${usd(check.cents)}` : "Add funds"}
              </button>
              <p className="flex items-center justify-center gap-1.5 text-center text-[11.5px] text-tx-faint">
                <Icon name="shieldcheck" size={11} tone="inherit" /> Secure card checkout powered by Stripe
              </p>
            </form>
          )}

          {step.s === "pay" && (
            <div className="flex flex-col gap-3">
              <div className="flex items-center justify-between rounded-[12px] border border-rim-hi bg-well px-4 py-3">
                <span className="text-[13px] text-tx-mute">Adding to your wallet</span>
                <span className="num text-[16px] font-extrabold text-white">{usd(step.cents)}</span>
              </div>
              <TopUpPayment
                clientSecret={step.clientSecret}
                publishableKey={step.publishableKey}
                amountCents={step.cents}
                local={step.local}
                onPaid={(id) => onPaid(id, step.cents)}
              />
              <button
                type="button"
                onClick={() => setStep({ s: "amount" })}
                className="self-center text-[12.5px] font-semibold text-tx-mute hover:text-white"
              >
                ← Change amount
              </button>
            </div>
          )}

          {step.s === "done" && (
            <div className="flex flex-col items-center gap-3 py-2 text-center">
              <span className="grid h-14 w-14 place-items-center rounded-full border border-mint/40 bg-mint/10 text-mint" aria-hidden>
                <Icon name="checkcircle" size={22} tone="inherit" />
              </span>
              <p className="text-[15px] font-bold text-white">{usd(step.cents)} added to your wallet</p>
              {step.balanceCents !== null && (
                <p className="text-[13px] text-tx-mute" data-testid="add-funds-new-balance">
                  New balance <span className="num font-extrabold text-white">{usd(step.balanceCents)}</span>
                </p>
              )}
              <p className="text-[12px] text-tx-faint">A receipt is on its way to your email and in Billing.</p>
              <div className="mt-2 flex w-full gap-2">
                <Link href="/dashboard/billing" onClick={onClose} className="btn-secondary h-[42px] flex-1 text-[13px]">View billing</Link>
                <button type="button" onClick={onClose} className="btn-primary h-[42px] flex-1 text-[13px]">Done</button>
              </div>
            </div>
          )}

          {step.s === "pending" && (
            <div className="flex flex-col items-center gap-3 py-2 text-center">
              <span className="grid h-14 w-14 place-items-center rounded-full border border-cyan/40 bg-cyan/10 text-cyan" aria-hidden>
                <Icon name="refresh" size={22} tone="inherit" />
              </span>
              <p className="text-[15px] font-bold text-white">Your payment of {usd(step.cents)} is processing</p>
              <p className="text-[12.5px] leading-[1.5] text-tx-mute">
                It will appear in your wallet as soon as it is confirmed, usually within a minute. You don&apos;t need to pay again.
              </p>
              <button type="button" onClick={onClose} className="btn-primary mt-2 h-[42px] w-full text-[13px]">Done</button>
            </div>
          )}
        </div>
      </div>
    </div>,
    document.body,
  );
}

