              >
                ← Change amount
              </button>
            </div>
          )}

          {step.s === "done" && (
            <div className="flex flex-col items-center gap-3 py-2 text-center">
              <span className="grid h-14 w-14 place-items-center rounded-full border border-mint/40 bg-mint/10 text-mint" aria-hidden>
                <Icon name="checkcircle" size={22} tone="inherit" />
              </span>
              <p className="text-[15px] font-bold text-white">{usd(step.cents)} added to your wallet</p>
              {step.balanceCents !== null && (
                <p className="text-[13px] text-tx-mute" data-testid="add-funds-new-balance">
                  New balance <span className="num font-extrabold text-white">{usd(step.balanceCents)}</span>
                </p>
              )}
              <p className="text-[12px] text-tx-faint">A receipt is on its way to your email and in Billing.</p>
              <div className="mt-2 flex w-full gap-2">
                <Link href="/dashboard/billing" onClick={onClose} className="btn-secondary h-[42px] flex-1 text-[13px]">View billing</Link>
                <button type="button" onClick={onClose} className="btn-primary h-[42px] flex-1 text-[13px]">Done</button>
              </div>
            </div>
          )}

          {step.s === "pending" && (
            <div className="flex flex-col items-center gap-3 py-2 text-center">
              <span className="grid h-14 w-14 place-items-center rounded-full border border-cyan/40 bg-cyan/10 text-cyan" aria-hidden>
                <Icon name="refresh" size={22} tone="inherit" />
              </span>
              <p className="text-[15px] font-bold text-white">Your payment of {usd(step.cents)} is processing</p>
              <p className="text-[12.5px] leading-[1.5] text-tx-mute">
                It will appear in your wallet as soon as it is confirmed, usually within a minute. You don&apos;t need to pay again.
              </p>
              <button type="button" onClick={onClose} className="btn-primary mt-2 h-[42px] w-full text-[13px]">Done</button>
            </div>
          )}
        </div>
      </div>
    </div>,
    document.body,
  );
}

