import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { decideTopUpCompletion, looksLikeCheckoutSessionId, validateTopUpAmount, TOPUP_PRESETS } from "../lib/topup-inplace.ts";

const root = join(import.meta.dirname, "..");
const src = (p: string) => readFileSync(join(root, p), "utf8");

test("only the paying account's own, paid session is completed in place", () => {
  assert.deepEqual(decideTopUpCompletion({ metadata: { nxeonUserId: "u1" }, payment_status: "paid" }, "u1"), { kind: "ok" });
  assert.deepEqual(decideTopUpCompletion({ metadata: { nxeonUserId: "u2" }, payment_status: "paid" }, "u1"), { kind: "forbidden" });
  assert.deepEqual(decideTopUpCompletion({ metadata: {}, payment_status: "paid" }, "u1"), { kind: "forbidden" });
  assert.deepEqual(decideTopUpCompletion({ metadata: null, payment_status: "paid" }, "u1"), { kind: "forbidden" });
  assert.deepEqual(decideTopUpCompletion({ metadata: { nxeonUserId: "u1" }, payment_status: "unpaid" }, "u1"), { kind: "pending" });
});

test("session ids are shape-checked before any Stripe call", () => {
  assert.equal(looksLikeCheckoutSessionId("cs_test_a1B2c3D4e5F6g7H8"), true);
  assert.equal(looksLikeCheckoutSessionId("cs_live_a1B2c3D4e5F6g7H8"), true);
  for (const bad of ["", "pi_123", "cs_test_", "cs_test_../../x", 42, null, undefined, "cs_test_" + "a".repeat(400)]) {
    assert.equal(looksLikeCheckoutSessionId(bad), false, String(bad));
  }
});

test("amount validation mirrors the checkout route's limits", () => {
  assert.deepEqual(validateTopUpAmount("25"), { ok: true, cents: 2500 });
  assert.deepEqual(validateTopUpAmount("12.345"), { ok: true, cents: 1235 });
  assert.equal(validateTopUpAmount("4.99").ok, false);
  assert.equal(validateTopUpAmount("5001").ok, false);
  assert.equal(validateTopUpAmount("").ok, false);
  assert.equal(validateTopUpAmount("abc").ok, false);
  assert.deepEqual(validateTopUpAmount("5000"), { ok: true, cents: 500000 });
  // an admin-raised minimum is respected and worded
  const r = validateTopUpAmount("8", 1000);
  assert.equal(r.ok, false);
  assert.match(!r.ok ? r.error : "", /\$10\.00/);
  for (const p of TOPUP_PRESETS) assert.equal(validateTopUpAmount(String(p)).ok, true);
});

test("sidebar Add funds opens the popup instead of linking to Billing", () => {
  const shell = src("components/nx/Shell.tsx");
  const balance = shell.slice(shell.indexOf("function Balance("), shell.indexOf("function ShellInner("));
  assert.ok(balance.includes("<AddFundsDialog"), "Balance renders the dialog");
  assert.ok(!/<Link href="\/dashboard\/billing"[^>]*>Add funds<\/Link>/.test(balance), "no navigation link left");
});

test("the popup completes through the shared fulfilment, never a second credit path", () => {
  const route = src("app/api/stripe/topup-complete/route.ts");
  assert.ok(route.includes("retrieveCheckoutSession("), "re-reads the session from Stripe");
  assert.ok(route.includes("decideTopUpCompletion("), "ownership + paid check");
  assert.ok(route.includes("fulfilRetrievedCheckoutSession("), "same idempotent fulfilment as confirm + webhook");
  assert.ok(!/balanceCents:\s*\{\s*increment/.test(route), "never credits the wallet itself");
  const dialog = src("components/nx/AddFundsDialog.tsx");
  assert.ok(dialog.includes('"/api/stripe/checkout"'), "same checkout endpoint as Billing");
  assert.ok(dialog.includes("router.refresh()"), "refreshes the balance on success");
  const modal = src("components/customer/AddFundsPaymentModal.tsx");
  assert.ok(modal.includes('redirect: "if_required"'), "in-place confirm only when onPaid is given");
});
EOF
