/**
 * What the dashboard's "View status" popup (components/nx/NetworkStatusModal.tsx)
 * says when it cannot load /api/dashboard/network-status. It used to print one
 * line for every failure — "Couldn't load live status — try again in a moment."
 * — with no way to try again short of closing and reopening, and the same words
 * for a signed-out session (401), where trying again can never work.
 * `status` is the HTTP status, or null when the request never completed
 * (offline, timed out, aborted).
 */
export function statusLoadError(status: number | null): { message: string; retry: boolean; signIn: boolean } {
  if (status === 401) {
    return { message: "Your session has ended, so we couldn't load live status. Sign in again to see it.", retry: false, signIn: true };
  }
  if (status === null) {
    return { message: "We couldn't reach Nxeon to check live status. Check your connection, then try again.", retry: true, signIn: false };
  }
  return { message: "Live status didn't load this time. Try again, or open the full status page.", retry: true, signIn: false };
}
