import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { statusLoadError } from "../lib/status-copy.ts";

const root = join(import.meta.dirname, "..");
const view = readFileSync(join(root, "components/nx/DashboardView.tsx"), "utf8");
const modal = readFileSync(join(root, "components/nx/NetworkStatusModal.tsx"), "utf8");

/* The bug (2026-10-07): the dashboard locked itself to one viewport height from
   `lg` up, but only split into two columns from `xl` up. At 1024-1279px both
   columns were stacked into one screen, the rail painted over the bottom of the
   main column, and "View status" sat underneath the Matrix promo / Deploy tiles. */
test("the one-screen height lock starts at the same breakpoint as the two-column grid", () => {
  const lock = view.match(/\b(sm|md|lg|xl|2xl):h-\[calc\(100dvh-120px\)\]/);
  assert.ok(lock, "height lock class present");
  const grid = view.match(/\b(sm|md|lg|xl|2xl):grid-cols-\[minmax\(0,1fr\)_368px\]/);
  assert.ok(grid, "two-column grid class present");
  assert.equal(lock![1], grid![1], `height lock at ${lock![1]} but columns split at ${grid![1]}`);
  assert.ok(!/\blg:h-\[calc\(100dvh-120px\)\]/.test(view), "no lg-scoped lock left");
});

test("View status opens the popup, and the popup can recover from a failed load", () => {
  assert.match(view, /onClick=\{\(\) => setStatusOpen\(true\)\}[\s\S]{0,200}View status/);
  assert.ok(modal.includes("statusLoadError("), "uses the shared error wording");
  assert.ok(modal.includes("setAttempt("), "has a Try again that refetches");
  assert.ok(modal.includes("AbortController"), "a hung request times out instead of spinning forever");
  assert.ok(!modal.includes("try again in a moment"), "old dead-end message is gone");
});

test("load errors say what actually happened", () => {
  const signedOut = statusLoadError(401);
  assert.equal(signedOut.retry, false, "retrying a 401 can never work");
  assert.equal(signedOut.signIn, true);
  const offline = statusLoadError(null);
  assert.equal(offline.retry, true);
  assert.match(offline.message, /connection/i);
  for (const s of [500, 502, 503, 504]) {
    const e = statusLoadError(s);
    assert.equal(e.retry, true);
    assert.equal(e.signIn, false);
  }
  // Brand voice: Nxeon speaks as the owner; never blames a "provider".
  for (const s of [401, null, 502]) assert.ok(!/provider/i.test(statusLoadError(s).message));
});
EOF
